        UNION { VALUES ?root { wd:Q139528213 wd:Q22676898 wd:Q106535803 wd:Q2174695 wd:Q28739684 wd:Q2172777 wd:Q3900737 wd:Q811367 wd:Q2423400 wd:Q3556678 wd:Q15401756 wd:Q3840065 wd:Q1413664 wd:Q108296019 wd:Q792548 wd:Q340755 wd:Q11898965 wd:Q790454 wd:Q810225 wd:Q810451 } ?item wdt:P279 ?root }
        UNION { VALUES ?root { wd:Q139528213 wd:Q22676898 wd:Q106535803 wd:Q2174695 wd:Q28739684 wd:Q2172777 wd:Q3900737 wd:Q811367 wd:Q2423400 wd:Q3556678 wd:Q15401756 wd:Q3840065 wd:Q1413664 wd:Q108296019 wd:Q792548 wd:Q340755 wd:Q11898965 wd:Q790454 wd:Q810225 wd:Q810451 } BIND(?root AS ?item) }
